<?php
declare(strict_types=1);
/** Published visual-builder output for the homepage. Business data remains supplied by the existing routes. */
$pbUrl=static function(string $url):string{$url=trim($url);return $url!==''&&(preg_match('~^https?://~i',$url)||str_starts_with($url,'/'))?$url:'';};
$pbSlug=static function(string $value):string{$value=strtr(mb_strtolower(trim($value),'UTF-8'),['ı'=>'i','İ'=>'i','ğ'=>'g','Ğ'=>'g','ü'=>'u','Ü'=>'u','ş'=>'s','Ş'=>'s','ö'=>'o','Ö'=>'o','ç'=>'c','Ç'=>'c']);$value=preg_replace('/[^a-z0-9]+/','-', $value);return trim((string)$value,'-');};
$pbItems=$pageBuilderLayout['widgets']??[];
$pbFetchProperties=static function(string $type,array $settings,int $limit):array{
    $pdo=\App\Core\Database::connection();$where=["p.status='published'"];$args=[];
    foreach(['location_id'=>'p.location_city_id','category_id'=>'p.category_id'] as $key=>$column){$value=max(0,(int)($settings[$key]??0));if($value>0){$where[]=$column.'=?';$args[]=$value;}}
    $guests=max(0,(int)($settings['min_guests']??0));if($guests>0){$where[]='p.max_guests>=?';$args[]=$guests;}
    $min=max(0,(float)($settings['min_price']??0));if($min>0){$where[]='p.base_nightly_price>=?';$args[]=$min;}
    $max=max(0,(float)($settings['max_price']??0));if($max>0){$where[]='p.base_nightly_price<=?';$args[]=$max;}
    $sort=(string)($settings['sort_by']??'');if($type==='recent_properties')$sort='recent';elseif($type==='popular_properties'||($type==='featured'&&$sort===''))$sort='popular';
    $order=match($sort){'price_low'=>'p.base_nightly_price ASC','price_high'=>'p.base_nightly_price DESC','rating'=>'rating_average DESC,rating_count DESC','popular'=>'booking_count DESC,rating_average DESC,p.created_at DESC',default=>'p.created_at DESC,p.id DESC'};
    $sql="SELECT p.*,(SELECT pm.file_path FROM property_media pm WHERE pm.property_id=p.id ORDER BY pm.is_cover DESC,pm.sort_order,pm.id LIMIT 1) AS cover_image,(SELECT COUNT(*) FROM bookings b WHERE b.property_id=p.id AND b.status NOT IN ('cancelled','rejected')) AS booking_count,(SELECT AVG(r.rating) FROM reviews r WHERE r.property_id=p.id AND r.status='approved') AS rating_average,(SELECT COUNT(*) FROM reviews r WHERE r.property_id=p.id AND r.status='approved') AS rating_count FROM properties p WHERE ".implode(' AND ',$where)." ORDER BY ".$order." LIMIT ".max(1,min(24,$limit));
    $stmt=$pdo->prepare($sql);$stmt->execute($args);return $stmt->fetchAll(PDO::FETCH_ASSOC);
};
$pbFetchDestinations=static function(array $settings,int $limit):array{
    $pdo=\App\Core\Database::connection();$where=["p.status='published'","l.location_type='city'","l.is_active=1"];$args=[];$country=max(0,(int)($settings['country_id']??0));if($country>0){$where[]='l.parent_id=?';$args[]=$country;}
    $order=($settings['sort_by']??'')==='alphabetical'?'l.name ASC':'property_count DESC,l.sort_order,l.name';
    $sql="SELECT l.id AS location_id,l.name AS city,COUNT(DISTINCT p.id) AS property_count,(SELECT pm.file_path FROM property_media pm JOIN properties p2 ON p2.id=pm.property_id WHERE p2.status='published' AND p2.location_city_id=l.id ORDER BY pm.is_cover DESC,pm.sort_order,pm.id LIMIT 1) AS cover_image FROM locations l JOIN properties p ON p.location_city_id=l.id WHERE ".implode(' AND ',$where)." GROUP BY l.id,l.name,l.sort_order ORDER BY ".$order." LIMIT ".max(1,min(24,$limit));
    $stmt=$pdo->prepare($sql);$stmt->execute($args);return $stmt->fetchAll(PDO::FETCH_ASSOC);
};
$pbFetchReviews=static function(int $limit):array{
    $sql="SELECT r.rating,r.body,r.created_at,u.username,p.title AS property_title FROM reviews r JOIN users u ON u.id=r.guest_user_id JOIN properties p ON p.id=r.property_id WHERE r.status='approved' AND r.body IS NOT NULL AND TRIM(r.body)<>'' AND p.status='published' ORDER BY r.created_at DESC,r.id DESC LIMIT ".max(1,min(24,$limit));
    return \App\Core\Database::connection()->query($sql)->fetchAll(PDO::FETCH_ASSOC);
};
$pbFetchHosts=static function(int $limit):array{
    $pdo=\App\Core\Database::connection();$mode=(string)($pdo->query("SELECT setting_value FROM settings WHERE setting_key='app.mode' LIMIT 1")->fetchColumn()?:'single_vendor');if($mode!=='multi_vendor')return [];
    return $pdo->query("SELECT v.id,v.business_name,COUNT(p.id) AS property_count FROM vendors v LEFT JOIN properties p ON p.vendor_id=v.id AND p.status='published' WHERE v.status='approved' GROUP BY v.id,v.business_name ORDER BY property_count DESC,v.id DESC LIMIT ".max(1,min(24,$limit)))->fetchAll(PDO::FETCH_ASSOC);
};

